Override de inventoryTick() : logique par tick pour un item en inventaire

@Override
public boolean hurtEnemy(ItemStack stack, LivingEntity target,
                          LivingEntity attacker) {
    // endommager l'item d'une durabilité
    stack.hurtAndBreak(1, attacker,
        e -> e.broadcastBreakEvent(EquipmentSlot.MAINHAND));
    return true;
}
Override de hurtEnemy() : logique quand l'item frappe un ennemi

@Override
public ItemStack finishUsingItem(ItemStack stack, Level level, LivingEntity entity) {
    // appelé à la fin de l'usage continu (food, bow, etc.)
    if (entity instanceof Player player && !player.getAbilities().instabuild)
        stack.shrink(1);
    return stack;
}
Override de finishUsingItem() : fin d'un usage continu (nourriture, etc.)

InteractionResultHolder.success(stack)  // action réussie + animation de bras
InteractionResultHolder.consume(stack)  // consommé (édible / chargeable)
InteractionResultHolder.pass(stack)     // ne pas intercepter (laisser passer)
InteractionResultHolder.fail(stack)     // échec (afficher si besoin)
Les 4 résultats de InteractionResultHolder (méthode use())

InteractionResult.SUCCESS   // succès + animation de bras
InteractionResult.CONSUME   // succès sans animation
InteractionResult.PASS      // ne pas traiter
InteractionResult.FAIL      // échec (son d'échec)
Les 4 résultats de InteractionResult (méthode useOn() / interact())



public class MonEpee extends SwordItem {
    public MonEpee() {
        super(Tiers.IRON,   // tier (WOOD / STONE / IRON / GOLD / DIAMOND / NETHERITE)
              6,            // dégâts bonus (base 1 + tier + bonus)
              -2.4f,        // bonus de vitesse d'attaque (valeur négative)
              new Item.Properties());
    }
}
