// Tier custom : implémenter Tier (ou utiliser le enum Tiers)
// Tiers standard :
Tiers.WOOD, Tiers.STONE, Tiers.IRON,
Tiers.GOLD, Tiers.DIAMOND, Tiers.NETHERITE

// Tier custom dans un enum :
public enum ModTiers implements Tier {
    RUBY(3, 1500, 8.0f, 3.0f, 20, Ingredient.of(ModItems.RUBY.get()));
    // harvestLevel, uses, speed, attackDmgBonus, enchantmentValue, repairIngredient
    ...
}
Tiers d'outils (Tiers enum + Tier interface pour un tier custom)



// Écrire (crée le tag s'il n'existe pas)
