BlockState state = level.getBlockState(pos);
state.is(Blocks.STONE)                     // est ce bloc exact ?
state.is(BlockTags.LOGS)                   // est dans ce tag ?
state.getValue(BlockStateProperties.POWERED) // propriété d'état
state.getBlock()                           // l'objet Block
Lire l'état d'un bloc dans le monde (getBlockState)

// flags : 0=rien 1=voisins 2=client 3=(1|2) — utiliser 3 en général
